import{_ as i,l as o,o as e,c as l,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"生日攻击","description":"","frontmatter":{"title":"生日攻击","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/birthday-attack.md","filePath":"cs/birthday-attack.md","lastUpdated":1789023840000}'),p={name:"cs/birthday-attack.md"};function A(E,a,_,m,u,B){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="生日攻击" tabindex="-1">生日攻击 <a class="header-anchor" href="#生日攻击" aria-label="Permalink to &quot;生日攻击&quot;">​</a></h1><div class="epigraph"><p>在 $n$ 比特摘要上，随机尝试大约 $2^{n/2}$ 次就期望撞上碰撞。这不是实现 bug，是鸽笼的定量形式；签名哈希与分组大小都要按这个界留余量。</p><footer>—— 据鸽笼原理与随机映射的碰撞统计；Katz and Lindell；对照 van Oorschot and Wiener 的并行碰撞搜索</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/length-extension-hmac">HMAC</a>关掉长度扩展。主干<a href="/cs/hash-collision">哈希与碰撞</a>已点名生日界。缺口是<strong>定量</strong>：为何 128 比特碰撞边际不够当长期签名哈希，以及这与「原像 \\(2^n\\)」不是同一条轴。不给寻找碰撞的程序。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HMAC 假设底层哈希仍抗碰撞。若 \\(H\\) 输出 \\(n\\) 比特，生日悖论给出碰撞代价 \\(\\sim 2^{n/2}\\)。MD5 的 128 比特在分析下更早垮掉；即使理想随机函数，64 比特块密码的生日也限制密文量（如 3DES 的 Sweet32 一类观察）。缺口是把平方根界钉进参数选择。</p><h3 id="碰撞-原像" tabindex="-1">碰撞≠原像 <a class="header-anchor" href="#碰撞-原像" aria-label="Permalink to &quot;碰撞≠原像&quot;">​</a></h3><p>给定 \\(y\\) 找原像仍约 \\(2^n\\)。签名伪造更常吃碰撞或第二原像，取决于敌手能否选消息。</p><p><span class="marginnote">Katz–Lindell 的哈希定义把碰撞优势写成游戏。本课不复述某公开碰撞示例的构造步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 \\(n\\) 人中两人同生日的直觉过渡到 \\(2^{n/2}\\)。列出：哈希输出宽、分组大小、RNG 的状态碰撞。参数：SHA-256 的碰撞边际对今日签名够用；128 比特摘要不当新签名默认。</p>',12)),(e(),s(c,null,{default:r(()=>[h(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22n%20%E6%AF%94%E7%89%B9%E8%BE%93%E5%87%BA%22%5D%20--%3E%20BDAY%5B%22%E6%9C%9F%E6%9C%9B%202%5E%7Bn%2F2%7D%20%E6%AC%A1%E7%A2%B0%E6%92%9E%22%5D%0A%20%20BDAY%20--%3E%20HASH%5B%22%E9%80%89%E6%91%98%E8%A6%81%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20BDAY%20--%3E%20BLK%5B%22%E9%99%90%E5%88%B6%E5%90%8C%E4%B8%80%E5%AF%86%E9%92%A5%E4%B8%8B%E5%9D%97%E6%95%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计算安全要写清敌手查询次数。生日界是通用攻击，不依赖弱轮函数。它解释为何 AES 块 128 仍要限制数据量、为何 SHA-1 的 160 比特在碰撞轴上被放弃。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进入量子 Grover/BHT 的定量作业。公钥侧下一课 RSA：把哈希用进填充方案 OAEP，碰撞界变成填充安全的前置。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HMAC 仍要底层抗碰撞；碰撞代价是平方根。</li><li>输出宽与块大小都按 \\(2^{n/2}\\) 留余量。</li><li>碰撞轴与原像轴分开记账。</li><li>下一课 RSA 与 OAEP：填充把哈希接进公钥加密。</li><li>出处：Katz and Lindell；van Oorschot and Wiener；对照 NIST 对 SHA-1 的弃用。</li></ul>',8))])}const S=i(p,[["render",A]]);export{b as __pageData,S as default};
